  "scenario_id": "sc-21b383",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "TPD",
      "years": [2020, 2023],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.045/yr in A/E, peaking at +12.6% (A/E 1.126) in 2023",
      "confidence": 0.85,
      "evidence": [
        "ae_tpd_by_year.csv: A/E rises monotonically from 0.987 (2020) to 1.126 (2023), consistently exceeding Poisson sampling noise (~±0.03-0.04 for E≈900-1100). Reverts to 0.964 in 2024."
      ],
      "recommended_action": "Investigate TPD claim reporting, underwriting, or claims handling changes during 2021-2023. Determine whether the 2024 reversion reflects a sustainable normalization or a one-off correction. Review TPD frequency/severity assumptions for pricing and valuation adequacy."
    },
    {
      "benefit": "IP",
      "years": null,
      "pattern": "recovery",
      "direction": "decrease",
      "magnitude": "~-5.2% deviation in termination A/E (0.948)",
      "confidence": 0.75,
      "evidence": [
        "ae_ip_termination.csv: Injury/Accident termination A/E = 0.948, indicating ~5% fewer terminations/recoveries than expected. All other diagnoses (Cancer, Cardiovascular, Mental Health, Musculoskeletal, Other) cluster near baseline 1.0."
      ],
      "recommended_action": "Review Injury/Accident IP claim duration, recovery assumptions, and claims management practices. Evaluate whether extended durations impact reserving or pricing for this diagnosis, and check for external factors (e.g., treatment guidelines, policy wording) that may have slowed terminations."
    }
  ]
}

